/* ============================================
   BREADCRUMB COMPONENT
   Hierarchical navigation trail
   ============================================ */

.ds-breadcrumb {
  width: 100%;
}

/* ============================================
   LIST
   ============================================ */

.ds-breadcrumb__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--gap-050);
  list-style: none;
  margin: 0;
  padding: 0;
}

/* ============================================
   ITEM
   ============================================ */

.ds-breadcrumb__item {
  display: flex;
  align-items: center;
  gap: var(--gap-050);
}

/* ============================================
   LINK
   ============================================ */

.ds-breadcrumb__link {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-breadcrumb__link:hover {
  color: var(--color-text-primary);
  text-decoration: underline;
}

.ds-breadcrumb__link:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
  border-radius: var(--radius-200);
}

/* ============================================
   CURRENT (last item)
   ============================================ */

.ds-breadcrumb__current {
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-primary);
}

/* ============================================
   SEPARATOR
   ============================================ */

/*
   Size via --icon-size, never font-size: .material-symbols-rounded derives
   the glyph size AND the layout box from that one variable. Setting
   font-size alone shrank the glyph but left a 24px box around it, so the
   chevron floated above the text baseline. --icon-size-500 (20px) also
   matches the 20px line-height of the paragraph-sm labels either side.
*/
.ds-breadcrumb__separator {
  --icon-size: var(--icon-size-500);
  flex: none;
  color: var(--color-text-tertiary);
  user-select: none;
}

/* ============================================
   ELLIPSIS
   ============================================ */

.ds-breadcrumb__ellipsis {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  color: var(--color-text-tertiary);
  user-select: none;
}

import './Breadcrumb.css';
import '../../fonts/material-symbols.css';

export interface BreadcrumbItem {
  /** Display label */
  label: string;
  /** Link href — omit for the current / last item */
  href?: string;
}

export interface BreadcrumbProps {
  /** Ordered list of breadcrumb items */
  items: BreadcrumbItem[];
  /** Maximum visible items before collapsing (min 2: first + last) */
  maxItems?: number;
  /** Additional CSS classes */
  className?: string;
  /**
   * Accessible name for the nav landmark. Override when more than one
   * Breadcrumb can appear on a page — identically-named landmarks are
   * indistinguishable to assistive technology.
   */
  ariaLabel?: string;
}

/**
 * Breadcrumb shows the user's location within a page hierarchy.
 * Supports automatic collapsing of middle items when the list exceeds maxItems.
 */
export const Breadcrumb = ({
  items,
  maxItems,
  className = '',
  ariaLabel,
}: BreadcrumbProps) => {
  const baseClass = 'ds-breadcrumb';
  const classes = [baseClass, className].filter(Boolean).join(' ');

  const shouldCollapse = maxItems !== undefined && maxItems >= 2 && items.length > maxItems;

  let visibleItems: (BreadcrumbItem | 'ellipsis')[];

  if (shouldCollapse) {
    /* Show first item, ellipsis, then last (maxItems - 1) items */
    const tailCount = maxItems - 1;
    visibleItems = [
      items[0],
      'ellipsis' as const,
      ...items.slice(-tailCount),
    ];
  } else {
    visibleItems = [...items];
  }

  return (
    <nav className={classes} aria-label={ariaLabel || 'Breadcrumb'}>
      <ol className={`${baseClass}__list`}>
        {visibleItems.map((item, index) => {
          const isLast = index === visibleItems.length - 1;

          if (item === 'ellipsis') {
            return (
              <li key="ellipsis" className={`${baseClass}__item`} aria-hidden="true">
                <span className={`${baseClass}__separator material-symbols-rounded`}>chevron_right</span>
                <span className={`${baseClass}__ellipsis`}>&hellip;</span>
              </li>
            );
          }

          return (
            <li key={index} className={`${baseClass}__item`}>
              {index > 0 && (
                <span className={`${baseClass}__separator material-symbols-rounded`} aria-hidden="true">
                  chevron_right
                </span>
              )}
              {isLast || !item.href ? (
                <span className={`${baseClass}__current`} aria-current="page">
                  {item.label}
                </span>
              ) : (
                <a href={item.href} className={`${baseClass}__link`}>
                  {item.label}
                </a>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
};
